mapper.select:
SELECT a.session_id, a.parent_session_id, a.session_name, a.session_content, a.session_type, a.create_time, a.creator_id, a.object_type, a.object_id, a.enterprise_id, a.update_by, a.update_time, a.state, a.project_id, b.avatar FROM byai_session a LEFT JOIN ss_resource b ON a.object_id = b.resource_id
AND a.creator_id = #{creatorId}
AND a.enterprise_id = #{enterpriseId}
AND a.object_type = #{objectType}
AND a.object_id = #{objectId}
AND a.is_debug = #{isDebug}
AND a.session_type IN
#{item}
AND (UPPER(a.session_name) LIKE CONCAT('%', UPPER(#{searchKeyword}), '%') OR UPPER(a.session_content) LIKE CONCAT('%', UPPER(#{searchKeyword}), '%'))
ORDER BY COALESCE(a.update_time, a.create_time) DESC,a.create_time DESC

SELECT s.session_id, s.parent_session_id, s.session_name, s.session_content, s.session_type, s.create_time, s.creator_id, s.object_type, s.object_id, s.enterprise_id, CASE WHEN s.is_debug = 2 THEN 1 ELSE 0 END AS is_template, s.update_by, s.update_time, s.state FROM byai_session s
AND s.is_debug = #{isDebug} AND (s.state IS NULL OR s.state != 'DELETED')
AND EXISTS ( SELECT 1 FROM byai_session_ext b WHERE b.session_id = s.session_id AND b.ext_param_code = 'template_type' AND b.ext_param_value IN
#{templateType}
)
AND EXISTS ( SELECT 1 FROM byai_session_ext c WHERE c.session_id = s.session_id AND c.ext_param_code = 'terminal' AND c.ext_param_value IN
#{terminal}
)
AND s.session_name LIKE #{keyword}
AND s.creator_id = #{creatorId}
AND s.enterprise_id = #{enterpriseId}
ORDER BY
s.update_time s.session_name s.create_time
ASC DESC

SELECT a.session_id, a.parent_session_id, a.session_name, a.create_time, a.creator_id, a.object_type, a.object_id, a.session_content, a.session_type FROM byai_session a
AND a.creator_id = #{creatorId}
AND a.session_type = #{sessionType}
AND a.object_type = #{objectType}
AND a.object_id = #{objectId}
AND (a.session_name LIKE CONCAT('%', #{keyword}, '%') OR a.session_content LIKE CONCAT('%', #{keyword}, '%'))
order by a.create_time desc,a.update_time desc

mapper.update:
UPDATE byai_session
SET session_name = #{sessionName},
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE session_id = #{sessionId}
  AND EXISTS (
      SELECT 1
      FROM byai_session_ext
      WHERE byai_session_ext.session_id = byai_session.session_id
        AND byai_session_ext.ext_param_code = #{extParamCode}
  )
